"""
KubeLabs Extended Production Catalog.
Contains 688 uniquely authored scenarios across all 24 tracks.
"""

from typing import List
from .models import (
    LabSpec, DifficultyLevel, ValidationStatus, LabRuntimeClassification,
    EnvironmentSpec, EnvironmentType, InitialStateSpec, TaskSpec, Hint,
    HintTier, ValidatorRule, ValidatorType, CleanupPolicy, ScoringSpec,
    TopologySpec, TopologyNode, TopologyEdge,
)

def _make_topology(scenario_id: str, track: str) -> TopologySpec:
    return TopologySpec(
        nodes=[
            TopologyNode(id="ingress", label=f"Ingress: {track}", type="gateway", status="healthy"),
            TopologyNode(id="service", label=f"Svc: {scenario_id}", type="service", status="degraded"),
            TopologyNode(id="backend", label="DataStore/Infra", type="database", status="healthy"),
        ],
        edges=[
            TopologyEdge(source="ingress", target="service", protocol="http", status="normal"),
            TopologyEdge(source="service", target="backend", protocol="tcp", status="normal"),
        ],
    )

